def _wbudowane_logo(slug):
    """Logotypy wtopione w moduł — działają nawet wtedy, gdy w folderze
    programu nie ma żadnych plików graficznych."""
    global _LOGO_CACHE
    if _LOGO_CACHE is None:
        try:
            _LOGO_CACHE = json.loads(zlib.decompress(
                base64.b64decode(_LOGO_B64)).decode("utf-8"))
        except Exception:
            _LOGO_CACHE = {}
    dane = _LOGO_CACHE.get(slug)
    if not dane:
        return None
    try:
        px = QPixmap()
        px.loadFromData(base64.b64decode(dane), "PNG")
        return None if px.isNull() else px
    except Exception:
        return None




def _geo():
    """Kropki lądów, kropki Polski i kontur — rozpakowywane raz."""
    global _GEO
    if _GEO is None:
        _GEO = json.loads(zlib.decompress(base64.b64decode(_GEO_B64)).decode("utf-8"))
    return _GEO


# ─────────────────────────── dźwięk ───────────────────────────
# Własne, łagodne tony zamiast systemowych sygnałów Windows — tamte
# na wielu komputerach są dźwiękami OSTRZEŻEŃ i źle się kojarzą.
# Zasada: wszystko wznosi się wraz z postępem.
#   ladowanie  — miękkie, narastające przejście (prolog, pierścień)
#   glob       — ciepłe rozwinięcie akordu (pojawia się kula ziemska)
#   odkrycie   — czysty dzwonek (rozbłysk Polski, nazwa miasta)
#   rozped     — wznoszący szum (tunel prędkości)
#   krok1..8   — kolejne stopnie gamy przy odhaczaniu sklepów
#   spelnienie — rozwiązanie akordu w finale
#   przejscie  — powietrzne domknięcie przy rozpadzie ekranu

_DZWIEK_ON = True
_DZWIEK_LOG = []
_CZEST = 22050


def _wav(pr, cz=_CZEST):
    import struct
    d = b"".join(struct.pack("<h", max(-32767, min(32767, int(v * 32767)))) for v in pr)
    return (b"RIFF" + struct.pack("<I", 36 + len(d)) + b"WAVEfmt " +
            struct.pack("<IHHIIHH", 16, 1, 1, cz, cz * 2, 2, 16) +
            b"data" + struct.pack("<I", len(d)) + d)


def _pogłos(buf, ile=3, opoznienie=0.055, tlumienie=0.34):
    """Delikatna przestrzeń — dzięki niej ton brzmi miękko, a nie jak pisk."""
    out = list(buf)
    for k in range(1, ile + 1):
        prz = int(opoznienie * k * _CZEST)
        gl = tlumienie ** k
        for i in range(prz, len(out)):
            out[i] += buf[i - prz] * gl
    return out


def _ton(f, dl, gl=0.5, atak=0.012, harm=(1.0, 0.34, 0.12), krzywa=6.0):
    import math as _m
    n = int(dl * _CZEST)
    out = [0.0] * n
    for i in range(n):
        u = i / _CZEST
        env = min(1.0, u / atak) * _m.exp(-u * krzywa)
        s = 0.0
        for h, a in enumerate(harm, start=1):
            s += a * _m.sin(2 * _m.pi * f * h * u)
        out[i] = gl * env * s / sum(harm)
    return out


def _zlacz(*bufory):
    n = max(len(b) for b in bufory)
    out = [0.0] * n
    for b in bufory:
        for i, v in enumerate(b):
            out[i] += v
    return out


def _stopien(nr):
    """Pentatonika durowa — kolejne stopnie zawsze brzmią zgodnie."""
    tony = [0, 2, 4, 7, 9]
    return 523.25 * (2 ** ((tony[nr % 5] + 12 * (nr // 5)) / 12.0))


def _syntezuj(rodzaj):
    import math as _m, random as _r
    if rodzaj.startswith("krok"):
        try:
            nr = int(rodzaj[4:] or 1) - 1
        except Exception:
            nr = 0
        f = _stopien(nr)
        buf = _zlacz(_ton(f, 0.75, 0.42, 0.010, (1.0, 0.30, 0.10), 5.2),
                     _ton(f * 2.0, 0.45, 0.14, 0.008, (1.0, 0.18), 8.0),
                     _ton(f / 2.0, 0.60, 0.10, 0.020, (1.0,), 4.4))
        return _wav(_pogłos(buf))
    if rodzaj == "ladowanie":
        n = int(1.9 * _CZEST); out = [0.0] * n
        for i in range(n):
            u = i / n
            f = 262.0 * (2 ** (1.35 * u))                 # płynne wznoszenie
            env = min(1.0, i / (0.25 * _CZEST)) * (1.0 - 0.35 * u)
            out[i] = 0.26 * env * (_m.sin(2 * _m.pi * f * (i / _CZEST))
                                   + 0.22 * _m.sin(4 * _m.pi * f * (i / _CZEST)))
        for k in range(6):                                 # delikatne pulsy
            t0 = int((0.15 + k * 0.28) * _CZEST)
            for i, v in enumerate(_ton(_stopien(k), 0.30, 0.16, 0.006, (1.0, 0.2), 9.0)):
                if t0 + i < n:
                    out[t0 + i] += v
        return _wav(_pogłos(out, 2, 0.07, 0.28))
    if rodzaj == "glob":
        buf = _zlacz(_ton(196.0, 2.2, 0.26, 0.45, (1.0, 0.22), 1.5),
                     _ton(293.7, 2.2, 0.22, 0.55, (1.0, 0.18), 1.4),
                     _ton(392.0, 2.0, 0.18, 0.65, (1.0,), 1.6),
                     _ton(587.3, 1.6, 0.10, 0.80, (1.0,), 1.8))
        return _wav(_pogłos(buf, 3, 0.09, 0.30))
    if rodzaj == "odkrycie":
        buf = _zlacz(_ton(659.3, 1.5, 0.34, 0.010, (1.0, 0.26, 0.08), 3.0),
                     _ton(987.8, 1.1, 0.16, 0.012, (1.0, 0.15), 4.2),
                     _ton(329.6, 1.3, 0.14, 0.030, (1.0,), 3.4))
        return _wav(_pogłos(buf))
    if rodzaj == "rozped":
        n = int(1.15 * _CZEST); out = [0.0] * n; stan = 0.0
        for i in range(n):
            u = i / n
            a = 0.04 + 0.55 * (u ** 1.8)                   # filtr otwiera się
            stan += a * ((_r.random() * 2 - 1) - stan)
            out[i] = 0.30 * stan * (u ** 1.2)
        for i, v in enumerate(_ton(392.0, 1.1, 0.16, 0.5, (1.0, 0.2), 1.2)):
            if i < n:
                out[i] += v
        return _wav(out)
    if rodzaj == "spelnienie":
        buf = _zlacz(_ton(523.25, 2.4, 0.30, 0.020, (1.0, 0.28, 0.10), 1.7),
                     _ton(659.3, 2.4, 0.26, 0.10, (1.0, 0.20), 1.6),
                     _ton(784.0, 2.2, 0.22, 0.20, (1.0, 0.15), 1.6),
                     _ton(1046.5, 1.8, 0.14, 0.30, (1.0,), 1.8),
                     _ton(261.6, 2.6, 0.18, 0.05, (1.0, 0.3), 1.3))
        return _wav(_pogłos(buf, 4, 0.10, 0.32))
    if rodzaj == "przejscie":
        n = int(1.0 * _CZEST); out = [0.0] * n; stan = 0.0
        for i in range(n):
            u = i / n
            a = 0.5 * (1 - u) ** 1.5 + 0.03
            stan += a * ((_r.random() * 2 - 1) - stan)
            out[i] = 0.22 * stan * (1 - u) ** 0.8
        for i, v in enumerate(_ton(523.25, 0.9, 0.20, 0.015, (1.0, 0.2), 3.2)):
            if i < n:
                out[i] += v
        return _wav(_pogłos(out, 2, 0.08, 0.25))
    return _wav([0.0] * 200)


_PLIKI = {}


def _plik(rodzaj):
    if rodzaj in _PLIKI and os.path.exists(_PLIKI[rodzaj]):
        return _PLIKI[rodzaj]
    import tempfile
    kat = os.path.join(tempfile.gettempdir(), "pmt_dzwieki2")
    os.makedirs(kat, exist_ok=True)
    sc = os.path.join(kat, "pmt_%s.wav" % rodzaj)
    if not os.path.exists(sc):
        with open(sc, "wb") as f:
            f.write(_syntezuj(rodzaj))
    _PLIKI[rodzaj] = sc
    return sc


_EFEKTY = {}


def _zagraj(rodzaj, katalogi=()):
    """Własny plik dzwiek_<rodzaj>.wav w folderze programu ma pierwszeństwo;
    inaczej gramy tonem przygotowanym w module. Cisza nigdy nie przerywa intra."""
    if not _DZWIEK_ON:
        return
    sc = None
    try:
        for kat in katalogi:
            if not kat:
                continue
            p = os.path.join(kat, "dzwiek_%s.wav" % rodzaj)
            if os.path.exists(p):
                sc = p
                break
        if sc is None:
            sc = _plik(rodzaj)
    except Exception as e:
        _DZWIEK_LOG.append("%s przygotowanie: %s" % (rodzaj, e))
        return
    try:
        import winsound
        winsound.PlaySound(sc, winsound.SND_FILENAME | winsound.SND_ASYNC
                           | winsound.SND_NODEFAULT)
        _DZWIEK_LOG.append("%s winsound OK" % rodzaj)
        return
    except Exception as e:
        _DZWIEK_LOG.append("%s winsound: %s" % (rodzaj, e))
    try:
        from PyQt6.QtMultimedia import QSoundEffect
        from PyQt6.QtCore import QUrl
        ef = _EFEKTY.get(rodzaj)
        if ef is None:
            ef = QSoundEffect()
            ef.setSource(QUrl.fromLocalFile(sc))
            ef.setVolume(0.6)
            _EFEKTY[rodzaj] = ef
        ef.play()
        _DZWIEK_LOG.append("%s qt OK" % rodzaj)
    except Exception as e:
        _DZWIEK_LOG.append("%s qt: %s" % (rodzaj, e))


def _cisza():
    for ef in _EFEKTY.values():
        try:
            ef.stop()
        except Exception:
            pass
    try:
        import winsound
        winsound.PlaySound(None, winsound.SND_PURGE)
    except Exception:
        pass


def _dopisz_diag(tekst):
    """Dziennik intra (~/PMT_intro_diag.txt) przycinany do ostatnich 200
    linii, gdy przekroczy ~100 KB — inaczej rósł bez końca."""
    try:
        sciezka = os.path.join(os.path.expanduser("~"), "PMT_intro_diag.txt")
        try:
            if os.path.exists(sciezka) and os.path.getsize(sciezka) > 100000:
                with open(sciezka, encoding="utf-8", errors="ignore") as f:
                    ogon = f.readlines()[-200:]
                with open(sciezka, "w", encoding="utf-8") as f:
                    f.writelines(ogon)
        except Exception:
            pass
        with open(sciezka, "a", encoding="utf-8") as f:
            f.write(str(tekst).rstrip("\n") + "\n")
    except Exception:
        pass


def _zapisz_dziennik_dzwieku():
    try:
        if not _DZWIEK_LOG:
            return
        _dopisz_diag("dźwięk: " + " | ".join(_DZWIEK_LOG[-14:]))
    except Exception:
        pass


