def _slug_sieci(nazwa):
    """Rozpoznaje sieć po POCZĄTKU nazwy: „Żabka Myśliborska 70A",
    „BIEDRONKA nr 4412", „abc Po sąsiedzku" trafiają do właściwego
    logotypu. None = sieć spoza naszej bazy."""
    n = (nazwa or "").upper().strip()
    if not n:
        return None
    for pelna, slug in _SLUG.items():
        if n == pelna or n.startswith(pelna) or (" " + pelna) in n:
            return slug
    return None

