# ─────────────────────────── pomoce geometryczne ───────────────────────────
def _catmull(p, seg):
    o, n = [], len(p)
    for i in range(n - 1):
        p0 = p[max(0, i - 1)]; p1 = p[i]; p2 = p[i + 1]; p3 = p[min(n - 1, i + 2)]
        for s in range(seg):
            u = s / seg; u2 = u * u; u3 = u2 * u
            o.append((0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * u
                             + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2
                             + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3),
                      0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * u
                             + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2
                             + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3)))
    o.append(p[-1])
    return o


def _slalom(p, a0, a1, prop):
    n, o = len(p), []
    for i, q in enumerate(p):
        f = i / max(1, n - 1)
        pr = p[max(0, i - 1)]; ne = p[min(n - 1, i + 1)]
        tx, ty = ne[0] - pr[0], ne[1] - pr[1]
        d = math.hypot(tx, ty) or 1.0
        tx /= d; ty /= d
        a = a0 + (a1 - a0) * f
        s = math.sin(f * prop * math.pi * 2)
        o.append((q[0] - ty * a * s, q[1] + tx * a * s))
    return o


def _rowno(p, n):
    cum = [0.0]
    for i in range(1, len(p)):
        cum.append(cum[-1] + math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]))
    L = cum[-1] or 1.0
    o = []
    for k in range(n):
        s = L * k / (n - 1)
        i = 1
        while i < len(cum) - 1 and cum[i] < s:
            i += 1
        u = (s - cum[i - 1]) / max(1e-9, cum[i] - cum[i - 1])
        o.append((p[i - 1][0] + (p[i][0] - p[i - 1][0]) * u,
                  p[i - 1][1] + (p[i][1] - p[i - 1][1]) * u))
    return o


def _plynnie(x):
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def _sfera(lat, lon, r=1.0):
    a = math.radians(lat); b = math.radians(lon)
    return (r * math.cos(a) * math.sin(b), r * math.sin(a), r * math.cos(a) * math.cos(b))


# ═══════════════════════════ nakładka ═══════════════════════════
if Qt is not None:

    class IntroZywaMapa(QWidget):
        """Pełna sekwencja intra jako nakładka wewnątrz okna programu."""

        zakonczony = pyqtSignal()
        daneGotowe = pyqtSignal(dict)

        # oś czasu (sekundy)
        T_PROLOG = 2.10                      # logo + pierścień ładowania
        T_GLOB0, T_GLOB1 = 2.25, 7.60
        T_TUNEL = 8.25
        T_MAPA0, T_MAPA1 = 8.25, 17.10      # jazda po pętli
        T_LOT0, T_LOT1 = 17.10, 18.05       # logo leci na środek
        T_RING0, T_RING1 = 18.05, 19.10     # pierścień 100 %
        T_ROZPAD0, T_ROZPAD1 = 19.10, 20.40
        T_KONIEC = 20.55

        def __init__(self, rodzic, dane, katalog_zasobow="", ciemny=True):
            super().__init__(rodzic)
            self.dane = dict(DANE_DEMO)
            self.dane.update(dane or {})
            self.kat = katalog_zasobow or ""
            self.ciemny = bool(ciemny)
            self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, False)
            self.setMouseTracking(True)
            try:
                rodzic.installEventFilter(self)
                self.setGeometry(rodzic.rect())
            except Exception:
                pass

            self._t = 0.0
            self._zeg = QElapsedTimer(); self._zeg.start()
            self._koniec_wyslany = False
            self._odhaczone = set()
            self._popupy = []
            self._v = 0.0          # prędkość wskazywana
            self._obr = 0.9        # obroty
            self._bieg = 1
            self._u_poprz = 0.0
            self._licznik_km = 0.0
            self.oszczedny = False
            self._wolne = 0
            self._kafle = None
            self._logo = self._wczytaj_logo("pmt_logo_retro.png", "pmt_logo.png",
                                            "logo_pmt.png", "pmt.png")   # to samo logo co po intrze
            self._logo_sieci = {}
            self._buduj_trase()
            self._buduj_swiat()

            self.daneGotowe.connect(self._przyjmij_dane)
            self._timer = QTimer(self)
            self._timer.timeout.connect(self._krok)
            self._timer.start(33)

        def showEvent(self, e):
            # zegar startuje dopiero przy realnym pokazaniu okna, żeby
            # długie wczytywanie programu nie zjadało początku animacji
            try:
                if not getattr(self, "_pokazano", False):
                    self._pokazano = True
                    self._zeg.restart()
                    self._t = 0.0
                    self._ost_rzecz = 0.0
            except Exception:
                pass
            super().showEvent(e)

        def _przyjmij_dane(self, nowe):
            """Dane z wątku w tle (plan wizyt) — wchodzą, dopóki trwa globus."""
            try:
                if not nowe or self._t > self.T_MAPA0 - 0.4:
                    return
                self.dane.update({k: v for k, v in nowe.items() if v})
                self._buduj_swiat()
                self._warstwa = None
                self._odhaczone = set()
            except Exception:
                pass

        # ---------- zasoby ----------
        def _sciezki_zasobow(self):
            k = self.kat
            sc = [k, os.path.join(k, "zasoby"), os.path.join(k, "zasoby", "logo"),
                  os.path.join(k, "logo"), os.getcwd()]
            # PyInstaller: pliki dołączone do EXE lądują w katalogu tymczasowym
            mei = getattr(sys, "_MEIPASS", None)
            if mei:
                sc = [mei, os.path.join(mei, "zasoby"),
                      os.path.join(mei, "zasoby", "logo"),
                      os.path.join(mei, "logo")] + sc
            try:
                sc.append(os.path.dirname(os.path.abspath(__file__)))
            except Exception:
                pass
            return sc

        def _wczytaj_logo(self, *nazwy):
            for kat in self._sciezki_zasobow():
                for n in nazwy:
                    p = os.path.join(kat, n)
                    if os.path.exists(p):
                        px = QPixmap(p)
                        if not px.isNull():
                            return px
            if any("pmt" in str(n).lower() for n in nazwy):
                return _wbudowane_logo("pmt")
            return None

        def _logo_sieci_px(self, siec):
            if siec in self._logo_sieci:
                return self._logo_sieci[siec]
            slug = _slug_sieci(siec)
            px = None
            if slug:
                px = self._wczytaj_logo("logo_%s.png" % slug, "%s.png" % slug,
                                        "logo_%s.jpg" % slug)
                if px is None:
                    px = _wbudowane_logo(slug)       # zapas wtopiony w moduł
            self._logo_sieci[siec] = px
            if px is None:
                _dopisz_diag("logo %s (%s): BRAK | szukano w: %s"
                             % (siec, slug, " ; ".join(self._sciezki_zasobow())))
            return px

        # ---------- świat ----------
        def _buduj_trase(self):
            p = _catmull(_PETLA, 10)
            p = _catmull(p, 6)
            p = _slalom(p, 0.034, 0.0, 1.78)
            p = _catmull(p, 6)
            p = _rowno(p, 900)
            p = _catmull(p, 3)
            self.trasa = _rowno(p, 1800)

        def _buduj_swiat(self):
            wezly = self.dane.get("wezly") or DANE_DEMO["wezly"]
            n = len(wezly)
            self.wezly = []
            for i, w in enumerate(wezly):
                f = 0.075 + (i / max(1, n - 1)) * 0.80
                idx = int(f * (len(self.trasa) - 1))
                self.wezly.append({"siec": w.get("siec", "?"), "adres": w.get("adres", ""),
                                   "km": w.get("km", 0), "f": f, "idx": idx})
            fs = [w["f"] for w in self.wezly] or [0.2, 0.5, 0.8]
            rnd = random.Random(20260902)
            self.pola = [max(0.03, fs[0] - 0.045),
                         (fs[len(fs) // 2] + fs[-1]) / 2.0,
                         min(0.95, fs[-1] + 0.03)]
            self.wies = min(0.95, fs[0] + 0.055)
            self.kosciol = min(0.95, self.wies + 0.030)
            self.rzeka = (fs[len(fs) // 3] + fs[len(fs) // 2]) / 2.0
            self.jezioro = max(0.05, fs[-1] - 0.14)
            self.wiatraki = max(0.05, fs[min(1, len(fs) - 1)] - 0.055)
            self.las = [max(0.04, fs[0] - 0.02), min(0.96, fs[-1] - 0.05)]
            self.slupy = [0.30, 0.62]
            self.drzewa = [{"f": (i * 0.0327 + 0.015) % 1.0,
                            "s": 0.55 + rnd.random() * 0.7,
                            "b": 1 if rnd.random() < 0.5 else -1} for i in range(34)]
            self.wzgorza = [(rnd.uniform(0.05, 0.95), rnd.uniform(0.10, 0.22),
                             rnd.uniform(0.06, 0.13)) for _ in range(7)]
            # meldunki systemowe
            mel = [(self.T_MAPA0 + 0.25, "Wyjazd: DOM 06:12")]
            zrobione = set()
            for i, w in enumerate(self.wezly):
                t = self.T_MAPA0 + 0.35 + w["f"] * (self.T_MAPA1 - self.T_MAPA0 - 0.6)
                if w["siec"] not in zrobione:
                    zrobione.add(w["siec"])
                    mel.append((t, "Węzeł %s potwierdzony ✓" % w["siec"]))
                if i + 1 < len(self.wezly):
                    nast = self.wezly[i + 1]
                    dk = max(3, int(nast["km"] - w["km"]))
                    mel.append((t + 0.45, "Kierunek: %s — %d km" % (nast["siec"], dk)))
            mel.append((self.T_MAPA1 - 0.35, "Pętla domknięta — powrót: DOM ✓"))
            self.meldunki = sorted(mel)

        # ---------- sterowanie ----------
        def _krok(self):
            poprz = self._t
            rzecz = self._zeg.elapsed() / 1000.0
            dt = rzecz - getattr(self, "_ost_rzecz", rzecz)
            self._ost_rzecz = rzecz
            # program potrafi zablokować wątek na sekundy (wczytywanie danych);
            # animacja ma wtedy poczekać, a nie przeskoczyć do finału
            self._t = poprz + max(0.0, min(dt, 0.12))
            if dt > 0.075:
                self._wolne += 1
                if self._wolne >= 6 and not self.oszczedny:
                    self.oszczedny = True
                    self._timer.setInterval(40)
            elif dt < 0.05:
                self._wolne = max(0, self._wolne - 1)
            if self._kafle is None and self._t >= self.T_ROZPAD0 - 0.12:
                self._przygotuj_kafle(float(self.width()), float(self.height()))
                _zagraj("przejscie", self._sciezki_zasobow())
            # dźwięk towarzyszy każdemu przełomowi opowieści
            for _kl, _prog in (("ladowanie", 0.20),
                               ("glob", self.T_GLOB0 + 0.10),
                               ("odkrycie", self.T_GLOB0 + 2.30),
                               ("odkrycie", self.T_GLOB1 - 1.15),
                               ("rozped", self.T_GLOB1 - 0.15),
                               ("spelnienie", self.T_RING0)):
                if poprz < _prog <= self._t:
                    _zagraj(_kl, self._sciezki_zasobow())
            if self._t >= self.T_KONIEC:
                self._zakoncz()
                return
            self.update()

        def _zakoncz(self):
            if self._koniec_wyslany:
                return
            self._koniec_wyslany = True
            _cisza()
            _zapisz_dziennik_dzwieku()
            try:
                self._timer.stop()
            except Exception:
                pass
            try:
                self.zakonczony.emit()
            except Exception:
                pass
            self.hide()
            self.deleteLater()

        def mousePressEvent(self, e):
            self._zakoncz()

        def keyPressEvent(self, e):
            self._zakoncz()

        def eventFilter(self, obj, ev):
            try:
                if ev.type().name == "Resize":
                    self.setGeometry(obj.rect())
            except Exception:
                pass
            return False

        # ---------- pomocnicze rysowanie ----------
        def _kadr(self, nx, ny, W, H):
            """Mapa mieści się w bezpiecznym polu: górny pas na powitanie,
            dolny na pasek stanu — koniec trasy nie ucieka za margines."""
            gora, dol, bok = 0.145, 0.150, 0.045
            return (bok * W + nx * W * (1.0 - 2 * bok),
                    gora * H + ny * H * (1.0 - gora - dol))

        def _przelicz_px(self, W, H):
            """Piksele trasy liczymy raz na rozmiar okna, nie co klatkę."""
            if getattr(self, "_px_rozmiar", None) == (W, H):
                return
            self._px_rozmiar = (W, H)
            px, py = self._kadr(_PIN[0], _PIN[1], W, H)
            N = len(self.trasa) - 1
            out = []
            for i, (nx, ny) in enumerate(self.trasa):
                x, y = self._kadr(nx, ny, W, H)
                f = i / N
                mk = max(_plynnie((f - 0.85) / 0.15), _plynnie((0.07 - f) / 0.07))
                out.append((x + (px - x) * mk, y + (py - y) * mk))
            self._trasa_px = out
            sc = QPainterPath()
            for i in range(0, len(out), 6):
                sc.moveTo(*out[i]) if i == 0 else sc.lineTo(*out[i])
            self._sciezka_cien = sc
            self._warstwa = None          # świat trzeba przerysować

        def _pkt(self, f, W, H):
            self._przelicz_px(W, H)
            f = max(0.0, min(1.0, f))
            return self._trasa_px[int(f * (len(self._trasa_px) - 1))]

        def _wek(self, f, W, H):
            a = self._pkt(max(0.0, f - 0.004), W, H)
            b = self._pkt(min(1.0, f + 0.004), W, H)
            tx, ty = b[0] - a[0], b[1] - a[1]
            d = math.hypot(tx, ty) or 1.0
            tx /= d; ty /= d
            return self._pkt(f, W, H), (tx, ty), (-ty, tx)

        def _zewn(self, x, y, nx, ny, W, H):
            return 1.0 if (x - W / 2) * nx + (y - H / 2) * ny >= 0 else -1.0

        def _pioro(self, p, kol, a, sz, mn):
            k = QColor(*kol)
            k.setAlphaF(max(0.0, min(1.0, a)))
            pen = QPen(k, max(1.0, mn * 0.0021 * sz))
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)

        # ═══════════ AKT 1: GLOBUS ═══════════
        def _globus_dane(self):
            if getattr(self, "_gl_cache", None) is None:
                g = _geo()
                self._gl_cache = (
                    [_sfera(la, lo) for la, lo in g["l"]],
                    [_sfera(la, lo) for la, lo in g["p"]],
                    [_sfera(la, lo) for lo, la in g["k"]])
            return self._gl_cache

        def _rysuj_globus(self, p, W, H, mn, t):
            lad3, pol3, kon3 = self._globus_dane()
            u = (t - self.T_GLOB0) / (self.T_GLOB1 - self.T_GLOB0)
            e1 = _plynnie(u / 0.42)
            e2 = _plynnie((u - 0.34) / 0.40)
            e3 = _plynnie((u - 0.66) / 0.34)
            lat = float(self.dane.get("lat", 52.25)); lon = float(self.dane.get("lon", 21.0))
            # docelowo: obrót = długość geograficzna, nachylenie = szerokość
            obrot = math.radians(lon) - 1.15 * (1.0 - _plynnie(u / 0.8))
            nachyl = math.radians(lat) * (0.25 + 0.75 * _plynnie(u / 0.75)) \
                + math.radians(16) * (1.0 - _plynnie(u / 0.6))
            R = mn * (0.34 + 0.62 * e2 + 1.55 * e3)
            cx, cy = W * 0.5, H * (0.50 + 0.16 * e3)

            so, co = math.sin(obrot), math.cos(obrot)
            sn, cn = math.sin(nachyl), math.cos(nachyl)

            def rzut3(v):
                x, y, z = v
                x2 = x * co - z * so
                z2 = x * so + z * co
                y2 = y * cn - z2 * sn
                z3 = y * sn + z2 * cn
                return cx + x2 * R, cy - y2 * R, z3

            def rzut(la, lo):
                return rzut3(_sfera(la, lo))

            # poświata i kula
            gr = QRadialGradient(QPointF(cx, cy), R * 1.6)
            gr.setColorAt(0.0, QColor(12, 60, 46, 180))
            gr.setColorAt(0.62, QColor(8, 34, 26, 90))
            gr.setColorAt(1.0, QColor(2, 10, 6, 0))
            p.setPen(Qt.PenStyle.NoPen); p.setBrush(gr)
            p.drawEllipse(QPointF(cx, cy), R * 1.55, R * 1.55)
            p.setBrush(QColor(3, 18, 13))
            p.drawEllipse(QPointF(cx, cy), R, R)

            # lądy
            rk = max(1.2, min(mn * 0.02, R * 0.022))
            krok = (3 if self.oszczedny else 2) if R < mn * 1.4 else (4 if self.oszczedny else 3)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, False)       # przy zbliżeniu rzadsza siatka
            pen = QPen(QColor(42, 168, 119, 215), rk)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            wid = QPolygonF()
            for v in lad3[::krok]:
                x, y, z = rzut3(v)
                if z > 0 and -mn < x < W + mn and -mn < y < H + mn:
                    wid.append(QPointF(x, y))
            if wid.count():
                p.drawPoints(wid)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            jas = 150 + int(105 * _plynnie(u / 0.5))
            pen = QPen(QColor(230, 255, 245, min(255, jas)), rk * 1.4)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            wid = QPolygonF()
            for v in pol3:
                x, y, z = rzut3(v)
                if z > 0:
                    wid.append(QPointF(x, y))
            if wid.count():
                p.drawPoints(wid)
            # kontur Polski rysowany na żywo
            kf = _plynnie((u - 0.18) / 0.34)
            if kf > 0:
                sc = QPainterPath(); zac = False
                for v in kon3[:max(2, int(len(kon3) * kf))]:
                    x, y, z = rzut3(v)
                    if z <= 0:
                        zac = False; continue
                    if not zac:
                        sc.moveTo(x, y); zac = True
                    else:
                        sc.lineTo(x, y)
                self._pioro(p, (141, 255, 210), 0.35 + 0.55 * kf, 2.6, mn)
                p.drawPath(sc)

            # miasto: pulsujący pierścień + nazwa
            mx, my, mz = rzut(lat, lon)
            if mz > 0:
                pu = (t * 1.5) % 1.0
                self._pioro(p, (141, 255, 210), (1 - pu) * (0.35 + 0.65 * e2), 2.0, mn)
                p.drawEllipse(QPointF(mx, my), mn * 0.012 + pu * mn * 0.085,
                              mn * 0.012 + pu * mn * 0.085)
                p.setPen(Qt.PenStyle.NoPen); p.setBrush(QColor(236, 255, 246, 240))
                p.drawEllipse(QPointF(mx, my), mn * 0.007, mn * 0.007)
                if e2 > 0.15:
                    f = QFont("Segoe UI", 1); f.setPixelSize(int(mn * (0.030 + 0.02 * e3)))
                    f.setBold(True); p.setFont(f)
                    k = QColor(236, 255, 246); k.setAlphaF(max(0.0, min(1.0, min(1.0, e2 * 1.4))))
                    p.setPen(k)
                    p.drawText(QRectF(mx - mn * 0.6, my - mn * 0.10, mn * 1.2, mn * 0.06),
                               Qt.AlignmentFlag.AlignCenter,
                               str(self.dane.get("miasto", "")).upper())
            # satelita na orbicie i łuki tras między miastami
            if e1 > 0.05:
                for i, (mla, mlo) in enumerate(((50.06, 19.94), (53.13, 23.16),
                                                (51.11, 17.03), (54.35, 18.65),
                                                (52.41, 16.93), (51.76, 19.46))):
                    kf = _plynnie((u - 0.18 - i * 0.045) / 0.18)
                    if kf <= 0:
                        continue
                    x1, y1, z1 = rzut(lat, lon)
                    x2, y2, z2 = rzut(mla, mlo)
                    if z1 <= 0 and z2 <= 0:
                        continue
                    sc = QPainterPath(); sc.moveTo(x1, y1)
                    mxp = (x1 + x2) / 2 + (y2 - y1) * 0.18
                    myp = (y1 + y2) / 2 - (x2 - x1) * 0.18
                    sc.quadTo(mxp, myp, x1 + (x2 - x1) * kf, y1 + (y2 - y1) * kf)
                    self._pioro(p, (141, 255, 210), 0.30 * kf * (1 - e3), 1.2, mn)
                    p.drawPath(sc)
                    p.setPen(Qt.PenStyle.NoPen)
                    k = QColor(236, 255, 246); k.setAlphaF(max(0.0, min(1.0, 0.7 * kf * (1 - e3))))
                    p.setBrush(k)
                    p.drawEllipse(QPointF(x1 + (x2 - x1) * kf, y1 + (y2 - y1) * kf),
                                  mn * 0.004, mn * 0.004)
                sa = t * 1.1
                sx = cx + math.cos(sa) * R * 1.24
                sy = cy + math.sin(sa) * R * 1.24 * 0.42
                self._pioro(p, (159, 212, 184), 0.35 * (1 - e3), 1.0, mn)
                p.drawEllipse(QPointF(cx, cy), R * 1.24, R * 1.24 * 0.42)
                p.setPen(Qt.PenStyle.NoPen); p.setBrush(QColor(236, 255, 246, 230))
                p.drawEllipse(QPointF(sx, sy), mn * 0.006, mn * 0.006)

            # napis POLSKA
            if 0.12 < u < 0.72:
                a = _plynnie((u - 0.12) / 0.2) * (1 - _plynnie((u - 0.58) / 0.14))
                f = QFont("Segoe UI", 1); f.setPixelSize(int(mn * 0.075)); f.setBold(True)
                p.setFont(f)
                k = QColor(180, 255, 226); k.setAlphaF(max(0.0, min(1.0, 0.85 * a))); p.setPen(k)
                p.drawText(QRectF(0, H * 0.10, W, mn * 0.11),
                           Qt.AlignmentFlag.AlignCenter, "P O L S K A")

        def _rysuj_prolog(self, p, W, H, mn, t):
            """Logo z zielonym pierścieniem ładowania — jak w starszych
            wersjach programu; pod spodem odliczanie procentów."""
            zn = 1.0 - _plynnie((t - self.T_PROLOG) / 0.35)
            if zn <= 0:
                return
            p.fillRect(QRectF(0, 0, W, H), QColor(2, 12, 8, int(255 * min(1.0, zn))))
            cx, cy = W * 0.5, H * 0.46
            R = mn * 0.115
            k = _plynnie(t / (self.T_PROLOG - 0.25))
            rr = R * 1.42
            pen = QPen(QColor(18, 48, 36, int(220 * zn)), mn * 0.016)
            p.setPen(pen); p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(cx, cy), rr, rr)
            pen = QPen(QColor(16, 184, 129, int(255 * zn)), mn * 0.016)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawArc(QRectF(cx - rr, cy - rr, rr * 2, rr * 2), 90 * 16, -int(360 * 16 * k))
            p.setOpacity(zn)
            self._rysuj_logo(p, cx, cy, R, 1.0)
            p.setOpacity(1.0)
            f = QFont("Segoe UI", 1); f.setPixelSize(max(11, int(mn * 0.023))); f.setBold(True)
            p.setFont(f)
            kk = QColor(201, 238, 219); kk.setAlphaF(max(0.0, min(1.0, 0.9 * zn)))
            p.setPen(kk)
            p.drawText(QRectF(cx - rr * 2, cy + rr + mn * 0.03, rr * 4, mn * 0.05),
                       int(Qt.AlignmentFlag.AlignCenter),
                       "Ładowanie trasy… %d %%" % int(k * 100))

        # ═══════════ AKT 1b: TUNEL ═══════════
        def _rysuj_tunel(self, p, W, H, mn, t):
            u = (t - self.T_MAPA0 + 0.65) / 0.65
            u = max(0.0, min(1.0, u))
            rnd = random.Random(7)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(2, 12, 8, int(120 + 80 * u)))
            p.drawRect(QRectF(0, 0, W, H))
            for i in range(150):
                a = rnd.uniform(0, math.tau)
                d0 = rnd.uniform(0.05, 1.0)
                d = d0 + u * 1.6
                x1 = W / 2 + math.cos(a) * d * W * 0.7
                y1 = H / 2 + math.sin(a) * d * H * 0.7
                x2 = W / 2 + math.cos(a) * (d + 0.16) * W * 0.7
                y2 = H / 2 + math.sin(a) * (d + 0.16) * H * 0.7
                k = QColor(180, 255, 225); k.setAlphaF(max(0.0, min(1.0, 0.55 * (1 - d0) * max(0.0, min(1.0, u)))))
                p.setPen(QPen(k, max(1.0, mn * 0.004 * (1 - d0))))
                p.drawLine(QPointF(x1, y1), QPointF(x2, y2))

        # ═══════════ AKT 2: ŻYWA MAPA ═══════════
        def _rysuj_mape(self, p, W, H, mn, t):
            """Świat (pola, wieś, rzeka, lasy…) rysowany jest do warstwy i tylko
            przeklejany; co klatkę liczą się wyłącznie elementy ruchome."""
            self._przelicz_px(W, H)
            u_ter = _plynnie((t - self.T_MAPA0 - 0.35) / (self.T_MAPA1 - self.T_MAPA0 - 0.5))
            nowa = (getattr(self, "_warstwa", None) is None
                    or self._warstwa.width() != int(W)
                    or self._warstwa.height() != int(H))
            if nowa:
                self._warstwa = QPixmap(int(W), int(H))
                self._warstwa.fill(QColor(0, 0, 0, 0))
                self._warstwa_u = -1.0
            if u_ter > self._warstwa_u:
                pw = QPainter(self._warstwa)
                pw.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                try:
                    self._rysuj_swiat(pw, W, H, mn, t, u_ter, self._warstwa_u)
                finally:
                    pw.end()
                self._warstwa_u = u_ter
            p.drawPixmap(0, 0, self._warstwa)
            self._rysuj_ruch(p, W, H, mn, t, u_ter)

        def _nowy(self, prog, u_od, u_do):
            """Element rysujemy na warstwie dokładnie raz — w chwili,
            gdy przejazd mija jego próg."""
            return u_od < prog <= u_do

        def _rysuj_swiat(self, p, W, H, mn, t, u, u_od=-1.0):
            KRE = (150, 242, 214); DOMK = (170, 247, 226); WODA = (122, 216, 236)
            BIA = (238, 255, 251); OKNO = (255, 214, 120)
            alfa = _plynnie((t - self.T_MAPA0) / 0.55)

            if u_od < 0:                      # tło stałe — raz przy starcie
                for hx, hy, hr in self.wzgorza:
                    self._pioro(p, KRE, 0.16 * alfa, 1.0, mn)
                    p.drawArc(QRectF(hx * W - hr * W, H * 0.30 - hy * H * 0.5,
                                     hr * 2 * W, hy * H), 0, 180 * 16)

            if u_od < 0:
                # księżyc + ptaki
                kx, ky, kr = W * 0.155, H * 0.115, mn * 0.027
                sc = QPainterPath(); sc.addEllipse(QPointF(kx, ky), kr, kr)
                s2 = QPainterPath(); s2.addEllipse(QPointF(kx - kr * 0.42, ky - kr * 0.22), kr * 0.92, kr * 0.92)
                p.setPen(Qt.PenStyle.NoPen)
                k = QColor(226, 246, 252); k.setAlphaF(max(0.0, min(1.0, 0.85 * alfa))); p.setBrush(k)
                p.drawPath(sc.subtracted(s2))
                self._pioro(p, KRE, 0.45 * alfa, 1.0, mn)
                for bx, by, bs in ((W * .245, H * .132, mn * .009), (W * .272, H * .152, mn * .007),
                                   (W * .296, H * .128, mn * .008)):
                    p.drawArc(QRectF(bx - bs, by - bs, bs, bs * 2), 40 * 16, 120 * 16)
                    p.drawArc(QRectF(bx, by - bs, bs, bs * 2), 20 * 16, 120 * 16)

            # ── pola uprawne ──
            for pi, fp in enumerate(self.pola):
                if not self._nowy(fp + 0.05, u_od, u):
                    continue
                cz = 1.0
                (x, y), (tx, ty), (nx, ny) = self._wek(fp, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                cxp = x + nx * s * mn * 0.075; cyp = y + ny * s * mn * 0.075
                e1x, e1y = tx * mn * 0.075, ty * mn * 0.075
                e2x, e2y = nx * s * mn * 0.05, ny * s * mn * 0.05
                A = QPointF(cxp - e1x - e2x, cyp - e1y - e2y)
                B = QPointF(cxp + e1x - e2x, cyp + e1y - e2y)
                C = QPointF(cxp + e1x + e2x, cyp + e1y + e2y)
                D = QPointF(cxp - e1x + e2x, cyp - e1y + e2y)
                self._pioro(p, KRE, 0.34 * cz * alfa, 1.0, mn)
                p.drawPolygon(A, B, C, D)
                self._pioro(p, KRE, 0.22 * cz * alfa, 1.0, mn)
                for gg in range(1, int(7 * cz) + 1):
                    w_ = gg / 8.0
                    p.drawLine(QPointF(A.x() + (D.x() - A.x()) * w_, A.y() + (D.y() - A.y()) * w_),
                               QPointF(B.x() + (C.x() - B.x()) * w_, B.y() + (C.y() - B.y()) * w_))
                if pi == 1 and cz > 0.75:      # owce
                    self._pioro(p, BIA, 0.75 * alfa, 1.0, mn)
                    for ow in (-0.3, 0.05, 0.42):
                        p.drawEllipse(QPointF(cxp + e1x * ow, cyp + e1y * ow),
                                      mn * 0.0052, mn * 0.0034)
                if pi == 2 and cz > 0.85:      # silos
                    sx_ = cxp + e1x * 0.8; sy_ = cyp + e1y * 0.8
                    self._pioro(p, DOMK, 0.65 * alfa, 1.0, mn)
                    p.drawRect(QRectF(sx_ - mn * 0.006, sy_ - mn * 0.020, mn * 0.012, mn * 0.020))
                    p.drawArc(QRectF(sx_ - mn * 0.006, sy_ - mn * 0.026, mn * 0.012, mn * 0.012),
                              0, 180 * 16)

            # ── lasy ──
            for fl in self.las:
                if not self._nowy(fl + 0.05, u_od, u):
                    continue
                cz = 1.0
                (x, y), (tx, ty), (nx, ny) = self._wek(fl, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                for i in range(9):
                    q = (i - 4) / 4.0
                    bx = x + tx * q * mn * 0.075 + nx * s * mn * (0.055 + 0.02 * abs(q))
                    by = y + ty * q * mn * 0.075 + ny * s * mn * (0.055 + 0.02 * abs(q))
                    hh = mn * 0.020 * (0.7 + 0.5 * ((i * 7) % 3) / 2.0)
                    self._pioro(p, KRE, 0.5 * cz * alfa, 1.0, mn)
                    p.drawLine(QPointF(bx, by), QPointF(bx, by - hh))
                    p.drawEllipse(QPointF(bx, by - hh - hh * 0.42), hh * 0.55, hh * 0.55)

            # ── rzeka z mostem ──
            cz = 1.0
            if self._nowy(self.rzeka + 0.06, u_od, u):
                (x, y), (tx, ty), (nx, ny) = self._wek(self.rzeka, W, H)
                self._pioro(p, WODA, 0.55 * cz * alfa, 1.6, mn)
                for s_ in (-1, 1):
                    sc = QPainterPath()
                    for kk in range(-26, 27):
                        q = kk / 26.0
                        off = s_ * mn * 0.018 + math.sin(q * 7 + t) * mn * 0.006
                        px_ = x + tx * q * mn * 0.45 + nx * off
                        py_ = y + ty * q * mn * 0.45 + ny * off
                        sc.moveTo(px_, py_) if kk == -26 else sc.lineTo(px_, py_)
                    p.drawPath(sc)
                self._pioro(p, WODA, 0.3 * cz * alfa, 1.0, mn)
                for kk in range(-3, 4):
                    q = kk / 4.0
                    p.drawArc(QRectF(x + tx * q * mn * 0.3 - mn * 0.008,
                                     y + ty * q * mn * 0.3 - mn * 0.005,
                                     mn * 0.016, mn * 0.010), 20 * 16, 140 * 16)
                self._pioro(p, DOMK, 0.75 * cz * alfa, 1.4, mn)   # most
                for s_ in (-1, 1):
                    p.drawLine(QPointF(x - nx * mn * 0.032 + tx * s_ * mn * 0.019,
                                       y - ny * mn * 0.032 + ty * s_ * mn * 0.019),
                               QPointF(x + nx * mn * 0.032 + tx * s_ * mn * 0.019,
                                       y + ny * mn * 0.032 + ty * s_ * mn * 0.019))

            # ── jezioro z trzcinami ──
            cz = 1.0
            if self._nowy(self.jezioro + 0.06, u_od, u):
                (x, y), (tx, ty), (nx, ny) = self._wek(self.jezioro, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                cxl = x + nx * s * mn * 0.085; cyl = y + ny * s * mn * 0.085
                self._pioro(p, WODA, 0.55 * cz * alfa, 1.4, mn)
                p.drawEllipse(QPointF(cxl, cyl), mn * 0.055, mn * 0.030)
                self._pioro(p, WODA, 0.3 * cz * alfa, 1.0, mn)
                for i in range(3):
                    p.drawArc(QRectF(cxl - mn * (0.03 - i * 0.008), cyl - mn * 0.006,
                                     mn * (0.06 - i * 0.016), mn * 0.012), 0, 180 * 16)
                self._pioro(p, KRE, 0.5 * cz * alfa, 1.0, mn)
                for i in range(5):
                    rx = cxl - mn * 0.05 + i * mn * 0.022
                    p.drawLine(QPointF(rx, cyl + mn * 0.026), QPointF(rx + mn * 0.004, cyl + mn * 0.008))

            # ── wiatraki ──
            cz = 1.0
            if self._nowy(self.wiatraki + 0.06, u_od, u):
                (x, y), (tx, ty), (nx, ny) = self._wek(self.wiatraki, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                for off, sk in ((-0.055, 1.0), (0.02, 0.78), (0.085, 0.62)):
                    bx = x + tx * mn * off * 1.7 + nx * s * mn * 0.09
                    by = y + ty * mn * off * 1.7 + ny * s * mn * 0.09
                    hh = mn * 0.055 * sk
                    self._pioro(p, DOMK, 0.8 * cz * alfa, 1.2, mn)
                    p.drawLine(QPointF(bx - mn * 0.005 * sk, by), QPointF(bx - mn * 0.001 * sk, by - hh))
                    p.drawLine(QPointF(bx + mn * 0.005 * sk, by), QPointF(bx + mn * 0.001 * sk, by - hh))

            # ── wieś i kościół ──
            cz = 1.0
            if self._nowy(self.wies + 0.06, u_od, u):
                (x, y), (tx, ty), (nx, ny) = self._wek(self.wies, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                for off, sk in ((-0.05, 1.0), (0.0, 0.85), (0.055, 0.95), (0.105, 0.8)):
                    bx = x + tx * mn * off * 1.7 + nx * s * mn * 0.075
                    by = y + ty * mn * off * 1.7 + ny * s * mn * 0.075
                    ww, hh = mn * 0.026 * sk, mn * 0.019 * sk
                    self._pioro(p, DOMK, 0.85 * cz * alfa, 1.2, mn)
                    p.drawRect(QRectF(bx - ww / 2, by - hh, ww, hh))
                    p.drawLine(QPointF(bx - ww * 0.6, by - hh), QPointF(bx, by - hh - hh * 0.7))
                    p.drawLine(QPointF(bx, by - hh - hh * 0.7), QPointF(bx + ww * 0.6, by - hh))
                    if cz > 0.5:
                        k = QColor(*OKNO); k.setAlphaF(max(0.0, min(1.0, 0.85 * cz * alfa)))
                        p.setPen(Qt.PenStyle.NoPen); p.setBrush(k)
                        p.drawRect(QRectF(bx - ww * 0.18, by - hh * 0.72, ww * 0.22, hh * 0.3))
            cz = 1.0
            if self._nowy(self.kosciol + 0.06, u_od, u):
                (x, y), (tx, ty), (nx, ny) = self._wek(self.kosciol, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                bx = x + nx * s * mn * 0.085; by = y + ny * s * mn * 0.085
                ww, hh = mn * 0.020, mn * 0.030
                self._pioro(p, DOMK, 0.85 * cz * alfa, 1.2, mn)
                p.drawRect(QRectF(bx - ww / 2, by - hh, ww, hh))
                p.drawLine(QPointF(bx - ww * 0.5, by - hh), QPointF(bx, by - hh * 1.7))
                p.drawLine(QPointF(bx, by - hh * 1.7), QPointF(bx + ww * 0.5, by - hh))
                p.drawLine(QPointF(bx, by - hh * 1.7), QPointF(bx, by - hh * 2.1))
                p.drawLine(QPointF(bx - mn * 0.006, by - hh * 1.95), QPointF(bx + mn * 0.006, by - hh * 1.95))

            # ── linia energetyczna ──
            for fsl in self.slupy:
                if not self._nowy(fsl + 0.05, u_od, u):
                    continue
                cz = 1.0
                (x, y), (tx, ty), (nx, ny) = self._wek(fsl, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                pkty = []
                for i in (-1, 0, 1):
                    bx = x + tx * i * mn * 0.075 + nx * s * mn * 0.062
                    by = y + ty * i * mn * 0.075 + ny * s * mn * 0.062
                    hh = mn * 0.040
                    self._pioro(p, KRE, 0.45 * cz * alfa, 1.0, mn)
                    p.drawLine(QPointF(bx, by), QPointF(bx, by - hh))
                    p.drawLine(QPointF(bx - mn * 0.010, by - hh * 0.82), QPointF(bx + mn * 0.010, by - hh * 0.82))
                    pkty.append((bx, by - hh * 0.82))
                self._pioro(p, KRE, 0.3 * cz * alfa, 1.0, mn)
                for i in range(len(pkty) - 1):
                    a, b = pkty[i], pkty[i + 1]
                    sc = QPainterPath(); sc.moveTo(a[0], a[1])
                    sc.quadTo((a[0] + b[0]) / 2, (a[1] + b[1]) / 2 + mn * 0.012, b[0], b[1])
                    p.drawPath(sc)

            # ── drzewa wzdłuż trasy ──
            for d in self.drzewa:
                if not self._nowy(d["f"] + 0.04, u_od, u):
                    continue
                cz = 1.0
                (x, y), (tx, ty), (nx, ny) = self._wek(d["f"], W, H)
                s = self._zewn(x, y, nx, ny, W, H) * d["b"]
                bx = x + nx * s * mn * 0.042; by = y + ny * s * mn * 0.042
                hh = mn * 0.022 * d["s"]
                self._pioro(p, KRE, 0.55 * cz * alfa, 1.0, mn)
                p.drawLine(QPointF(bx, by), QPointF(bx, by - hh))
                p.drawEllipse(QPointF(bx, by - hh - hh * 0.42), hh * 0.55, hh * 0.55)

        def _rysuj_ruch(self, p, W, H, mn, t, u):
            KRE = (150, 242, 214); DOMK = (170, 247, 226); WODA = (122, 216, 236)
            BIA = (238, 255, 251); OKNO = (255, 214, 120)
            alfa = _plynnie((t - self.T_MAPA0) / 0.55)
            # ── śmigła wiatraków (kręcą się co klatkę) ──
            czw = _plynnie((u - self.wiatraki) / 0.06)
            if czw > 0:
                (x, y), (tx, ty), (nx, ny) = self._wek(self.wiatraki, W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                for off, sk in ((-0.055, 1.0), (0.02, 0.78), (0.085, 0.62)):
                    bx = x + tx * mn * off * 1.7 + nx * s * mn * 0.09
                    by = y + ty * mn * off * 1.7 + ny * s * mn * 0.09
                    hh = mn * 0.055 * sk
                    self._pioro(p, DOMK, 0.8 * czw * alfa, 1.2, mn)
                    a0 = t * 1.7 + off * 9
                    for b in range(3):
                        a = a0 + b * 2.094
                        p.drawLine(QPointF(bx, by - hh),
                                   QPointF(bx + math.cos(a) * mn * 0.030 * sk,
                                           by - hh + math.sin(a) * mn * 0.030 * sk))

            # ── pętla trasy: cień + świetlna wstęga ──
            self._pioro(p, KRE, 0.16 * alfa, 1.6, mn)
            p.drawPath(self._sciezka_cien)
            if u > 0:
                sc = QPainterPath()
                N = max(2, int(u * 420))
                for i in range(N):
                    q = self._pkt(u * i / (N - 1), W, H)
                    sc.moveTo(*q) if i == 0 else sc.lineTo(*q)
                k = QColor(140, 255, 210); k.setAlphaF(max(0.0, min(1.0, 0.30 * alfa)))
                p.setPen(QPen(k, mn * 0.014, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
                p.drawPath(sc)
                k = QColor(236, 255, 246); k.setAlphaF(max(0.0, min(1.0, 0.95 * alfa)))
                p.setPen(QPen(k, mn * 0.005, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
                p.drawPath(sc)
                gx, gy = self._pkt(u, W, H)
                # iskry lecące za pojazdem
                rnd2 = random.Random(int(t * 24))
                self._pioro(p, (200, 255, 232), 0.5 * alfa, 1.0, mn)
                for _ in range(0 if self.oszczedny else 7):
                    a_ = rnd2.uniform(0, math.tau); d_ = rnd2.uniform(0.004, 0.022) * mn
                    p.drawPoint(QPointF(gx + math.cos(a_) * d_, gy + math.sin(a_) * d_))
                # furgonetka jadąca trasą
                pa = self._pkt(max(0.0, u - 0.006), W, H)
                kat = math.degrees(math.atan2(gy - pa[1], gx - pa[0]))
                p.save(); p.translate(gx, gy); p.rotate(kat)
                self._pioro(p, (240, 255, 248), 0.95 * alfa, 1.3, mn)
                p.drawRoundedRect(QRectF(-mn * 0.017, -mn * 0.009, mn * 0.034, mn * 0.018),
                                  mn * 0.004, mn * 0.004)
                p.drawLine(QPointF(mn * 0.004, -mn * 0.009), QPointF(mn * 0.004, mn * 0.009))
                p.setPen(Qt.PenStyle.NoPen); p.setBrush(QColor(255, 214, 120, int(230 * alfa)))
                p.drawEllipse(QPointF(mn * 0.015, 0), mn * 0.003, mn * 0.003)
                p.restore()
                gr = QRadialGradient(QPointF(gx, gy), mn * 0.05)
                gr.setColorAt(0.0, QColor(255, 255, 255, 250))
                gr.setColorAt(0.32, QColor(140, 255, 210, 130))
                gr.setColorAt(1.0, QColor(16, 184, 129, 0))
                p.setPen(Qt.PenStyle.NoPen); p.setBrush(gr)
                p.drawEllipse(QPointF(gx, gy), mn * 0.05, mn * 0.05)

            # chmury dryfujące
            for i in range(0 if self.oszczedny else 3):
                cxx = ((t * 0.012 + i * 0.37) % 1.25 - 0.12) * W
                cyy = H * (0.12 + 0.05 * i)
                self._pioro(p, KRE, 0.12 * alfa, 1.0, mn)
                for dx, dy, rr in ((0, 0, 0.020), (0.018, -0.006, 0.014), (-0.02, -0.004, 0.012)):
                    p.drawEllipse(QPointF(cxx + dx * mn, cyy + dy * mn), mn * rr, mn * rr * 0.62)
            # klucz ptaków przelatujący przez kadr
            bt = (t * 0.055) % 1.4 - 0.2
            if 0 < bt < 1.2:
                bx0 = bt * W; by0 = H * (0.20 + 0.05 * math.sin(t * 0.8))
                self._pioro(p, KRE, 0.35 * alfa, 1.0, mn)
                for i in range(5):
                    ox = bx0 - i * mn * 0.024
                    oy = by0 + abs(i - 2) * mn * 0.011 + math.sin(t * 6 + i) * mn * 0.002
                    p.drawArc(QRectF(ox - mn * 0.008, oy - mn * 0.006, mn * 0.008, mn * 0.012),
                              40 * 16, 110 * 16)
                    p.drawArc(QRectF(ox, oy - mn * 0.006, mn * 0.008, mn * 0.012),
                              30 * 16, 110 * 16)
            # traktor orzący pierwsze pole
            cz = _plynnie((u - self.pola[0] - 0.02) / 0.05)
            if cz > 0:
                (x, y), (tx, ty), (nx, ny) = self._wek(self.pola[0], W, H)
                s = self._zewn(x, y, nx, ny, W, H)
                q = math.sin(t * 0.9) * 0.6
                bx = x + tx * q * mn * 0.06 + nx * s * mn * 0.075
                by = y + ty * q * mn * 0.06 + ny * s * mn * 0.075
                self._pioro(p, DOMK, 0.8 * cz * alfa, 1.2, mn)
                p.drawRect(QRectF(bx - mn * 0.009, by - mn * 0.012, mn * 0.018, mn * 0.010))
                p.drawEllipse(QPointF(bx - mn * 0.007, by), mn * 0.005, mn * 0.005)
                p.drawEllipse(QPointF(bx + mn * 0.008, by - mn * 0.001), mn * 0.0075, mn * 0.0075)

            # ── DOM ──
            px_, py_ = self._kadr(_PIN[0], _PIN[1], W, H)
            pu = (t * 1.6) % 1.0
            self._pioro(p, (255, 168, 64), (1 - pu) * 0.9 * alfa, 1.4, mn)
            p.drawEllipse(QPointF(px_, py_), mn * 0.012 + pu * mn * 0.05, mn * 0.012 + pu * mn * 0.05)
            p.setPen(Qt.PenStyle.NoPen)
            k = QColor(255, 186, 92); k.setAlphaF(max(0.0, min(1.0, alfa))); p.setBrush(k)
            p.drawEllipse(QPointF(px_, py_), mn * 0.008, mn * 0.008)
            f = QFont("Segoe UI", 1); f.setPixelSize(max(10, int(mn * 0.019))); f.setBold(True)
            p.setFont(f)
            k = QColor(*KRE); k.setAlphaF(max(0.0, min(1.0, 0.9 * alfa))); p.setPen(k)
            p.drawText(QPointF(px_ + mn * 0.016, py_ + mn * 0.022), "DOM")

            # ── ODWIEDZONE PUNKTY: logotypy sieci + ✓ ──
            for i, w in enumerate(self.wezly):
                if u < w["f"] - 0.02:
                    continue
                poj = _plynnie((u - w["f"] + 0.02) / 0.05)
                qx, qy = self._pkt(w["f"], W, H)
                odwiedzony = u >= w["f"]
                if odwiedzony and i not in self._odhaczone:
                    self._odhaczone.add(i)
                    self._popupy.append([qx, qy, t])
                    _zagraj("krok%d" % min(8, len(self._odhaczone)), self._sciezki_zasobow())
                # pulsujący pierścień świeżej wizyty
                if odwiedzony:
                    pw = min(1.0, max(0.0, (u - w["f"]) / 0.06))
                    if pw < 1.0:
                        self._pioro(p, BIA, (1 - pw) * 0.8 * alfa, 1.4, mn)
                        p.drawEllipse(QPointF(qx, qy), mn * (0.010 + pw * 0.05),
                                      mn * (0.010 + pw * 0.05))
                self._pioro(p, BIA, 0.9 * alfa, 1.2, mn)
                p.drawEllipse(QPointF(qx, qy), mn * 0.009, mn * 0.009)
                # kaseton z logo
                px2 = self._logo_sieci_px(w["siec"])
                kw = mn * 0.125 * poj
                if px2 is not None and not px2.isNull():
                    kh = kw * px2.height() / max(1, px2.width())
                else:
                    # bez logo: kaseton dopasowany do długości nazwy sieci
                    fnt = QFont("Segoe UI", 1)
                    fnt.setPixelSize(max(9, int(mn * 0.023))); fnt.setBold(True)
                    try:
                        from PyQt6.QtGui import QFontMetricsF
                        szer = QFontMetricsF(fnt).horizontalAdvance(w["siec"])
                        wys = QFontMetricsF(fnt).height()
                    except Exception:
                        szer, wys = len(w["siec"]) * mn * 0.014, mn * 0.028
                    kw = (szer + mn * 0.028) * poj
                    kh = wys + mn * 0.010
                bx = qx - kw / 2; by = qy - mn * 0.030 - kh
                bx = max(mn * 0.02, min(W - kw - mn * 0.09, bx))
                by = max(mn * 0.02, min(H - kh - mn * 0.13, by))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(255, 255, 255, int(238 * poj)))
                p.drawRoundedRect(QRectF(bx - kw * 0.06, by - kh * 0.16,
                                         kw * 1.12, kh * 1.32), kh * 0.28, kh * 0.28)
                if px2 is not None and not px2.isNull():
                    p.setOpacity(poj)
                    p.drawPixmap(QRectF(bx, by, kw, kh), px2, QRectF(px2.rect()))
                    p.setOpacity(1.0)
                else:
                    kol = _BARWA_SIECI.get(w["siec"], (20, 120, 90))
                    k = QColor(*kol); k.setAlphaF(max(0.0, min(1.0, poj)))
                    p.setPen(k)
                    p.setFont(fnt)
                    p.drawText(QRectF(bx, by, kw, kh),
                               int(Qt.AlignmentFlag.AlignCenter), w["siec"])
                # znacznik odwiedzenia
                if odwiedzony:
                    k = QColor(16, 184, 129); k.setAlphaF(max(0.0, min(1.0, alfa)))
                    p.setPen(Qt.PenStyle.NoPen); p.setBrush(k)
                    r = kh * 0.42
                    p.drawEllipse(QPointF(bx + kw + kw * 0.02, by), r, r)
                    pen = QPen(QColor(255, 255, 255), max(1.4, r * 0.32))
                    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                    p.setPen(pen)
                    p.drawLine(QPointF(bx + kw + kw * 0.02 - r * 0.42, by),
                               QPointF(bx + kw + kw * 0.02 - r * 0.08, by + r * 0.36))
                    p.drawLine(QPointF(bx + kw + kw * 0.02 - r * 0.08, by + r * 0.36),
                               QPointF(bx + kw + kw * 0.02 + r * 0.46, by - r * 0.40))
                # adres pod pinezką
                if poj > 0.6 and w["adres"]:
                    f = QFont("Segoe UI", 1); f.setPixelSize(max(9, int(mn * 0.0165)))
                    p.setFont(f)
                    k = QColor(*KRE); k.setAlphaF(max(0.0, min(1.0, 0.8 * alfa))); p.setPen(k)
                    p.drawText(QPointF(qx + mn * 0.014, qy + mn * 0.020), w["adres"])

            # unoszące się potwierdzenia wizyt
            f = QFont("Segoe UI", 1); f.setPixelSize(max(10, int(mn * 0.020))); f.setBold(True)
            p.setFont(f)
            for pk in list(self._popupy):
                wiek = t - pk[2]
                if wiek > 1.4:
                    self._popupy.remove(pk); continue
                k = QColor(63, 224, 163); k.setAlphaF(max(0.0, min(1.0, max(0.0, 1.0 - wiek / 1.4) * alfa)))
                p.setPen(k)
                p.drawText(QPointF(pk[0] + mn * 0.016, pk[1] - mn * 0.02 - wiek * mn * 0.05),
                           "+1 wizyta")

            # ── ŻYWE ZEGARY: prędkościomierz i obrotomierz ──
            self._rysuj_zegary(p, W, H, mn, t, u, alfa)

            # ── meldunki systemowe ──
            akt = None
            for m in self.meldunki:
                if m[0] <= t:
                    akt = m
            if akt:
                n = max(0, int((t - akt[0]) * 26))
                f = QFont("Segoe UI", 1); f.setPixelSize(max(11, int(mn * 0.021))); f.setBold(True)
                p.setFont(f)
                k = QColor(*KRE); k.setAlphaF(max(0.0, min(1.0, 0.72 * alfa))); p.setPen(k)
                kur = "_" if int(t * 3.2) % 2 == 0 else " "
                p.drawText(QRectF(W * 0.052, H * 0.86, W * 0.7, mn * 0.05),
                           Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                           akt[1][:n] + kur)

        def _rysuj_zegary(self, p, W, H, mn, t, u, alfa):
            """Deska rozdzielcza: prędkość rośnie na prostych, spada do zera
            przy każdym sklepie, obrotomierz przerzuca biegi, licznik
            kilometrów odlicza dystans trasy."""
            KM = float(self.dane.get("km_dzis") or 42)
            # PRĘDKOŚĆ, OBROTY I RUCH AUTA MAJĄ JEDNO ŹRÓDŁO: tempo przejazdu
            # liczone NA SEKUNDĘ (wcześniej brałem przyrost na klatkę, przez co
            # wskazówka pokazywała ułamek tego, co widać na ekranie).
            dt = max(1e-3, t - getattr(self, "_t_zeg_poprz", t - 0.033))
            self._t_zeg_poprz = t
            du = max(0.0, u - self._u_poprz)
            self._u_poprz = u
            tempo = du / dt                      # ile trasy na sekundę
            cel = min(126.0, tempo * 560.0)      # przelot ≈ 85–105 km/h
            for w in self.wezly:
                d = abs(u - w["f"])
                if d < 0.030:
                    cel *= max(0.06, d / 0.030)
            if u <= 0.001 or u >= 0.999:
                cel = 0.0
            self._v += (cel - self._v) * (0.30 if cel > self._v else 0.22)
            self._licznik_km = KM * u
            # biegi: obroty rosną, przy przełożeniu opadają
            prog = (24, 45, 70, 98, 150)     # górny bieg ma realny zakres
            b = 1
            for i, g in enumerate(prog):
                if self._v > g:
                    b = i + 2
            self._bieg = min(5, b)
            dolna = prog[self._bieg - 2] if self._bieg > 1 else 0
            gorna = prog[self._bieg - 1]
            obr_cel = 0.85 + 5.4 * max(0.0, min(1.0, (self._v - dolna) / max(1.0, gorna - dolna)))
            if self._v < 2:
                obr_cel = 0.8 + 0.12 * math.sin(t * 7)
            self._obr += (obr_cel - self._obr) * 0.22

            def tarcza(cx, cy, r, wart, maks, opis, jedn, czerw=None, duza=True):
                self._pioro(p, (150, 242, 214), 0.40 * alfa, 1.4, mn)
                p.drawEllipse(QPointF(cx, cy), r, r)
                self._pioro(p, (150, 242, 214), 0.22 * alfa, 1.0, mn)
                p.drawEllipse(QPointF(cx, cy), r * 0.90, r * 0.90)
                start, zakres = 143.0, 254.0
                for i in range(11):
                    a = math.radians(start + zakres * i / 10.0)
                    dl = 0.13 if i % 2 == 0 else 0.07
                    czer = czerw is not None and (maks * i / 10.0) >= czerw
                    self._pioro(p, (255, 120, 110) if czer else (150, 242, 214),
                                (0.9 if czer else 0.55) * alfa, 1.2 if i % 2 == 0 else 1.0, mn)
                    p.drawLine(QPointF(cx + math.cos(a) * r * (0.86 - dl), cy + math.sin(a) * r * (0.86 - dl)),
                               QPointF(cx + math.cos(a) * r * 0.86, cy + math.sin(a) * r * 0.86))
                    if duza and i % 2 == 0:
                        f = QFont("Segoe UI", 1); f.setPixelSize(max(8, int(r * 0.16)))
                        p.setFont(f)
                        k = QColor(200, 245, 226); k.setAlphaF(max(0.0, min(1.0, 0.75 * alfa)))
                        p.setPen(k)
                        p.drawText(QRectF(cx + math.cos(a) * r * 0.63 - r * 0.22,
                                          cy + math.sin(a) * r * 0.63 - r * 0.14,
                                          r * 0.44, r * 0.28),
                                   int(Qt.AlignmentFlag.AlignCenter),
                                   str(int(maks * i / 10.0)))
                # wskazówka
                a = math.radians(start + zakres * max(0.0, min(1.0, wart / maks)))
                k = QColor(255, 236, 180); k.setAlphaF(max(0.0, min(1.0, 0.95 * alfa)))
                pen = QPen(k, max(1.6, r * 0.055)); pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                p.drawLine(QPointF(cx - math.cos(a) * r * 0.12, cy - math.sin(a) * r * 0.12),
                           QPointF(cx + math.cos(a) * r * 0.74, cy + math.sin(a) * r * 0.74))
                p.setPen(Qt.PenStyle.NoPen)
                k = QColor(255, 236, 180); k.setAlphaF(max(0.0, min(1.0, alfa)))
                p.setBrush(k)
                p.drawEllipse(QPointF(cx, cy), r * 0.07, r * 0.07)
                f = QFont("Segoe UI", 1); f.setPixelSize(max(9, int(r * 0.19))); f.setBold(True)
                p.setFont(f)
                k = QColor(238, 255, 251); k.setAlphaF(max(0.0, min(1.0, 0.9 * alfa)))
                p.setPen(k)
                p.drawText(QRectF(cx - r, cy + r * 0.30, r * 2, r * 0.34),
                           int(Qt.AlignmentFlag.AlignCenter), opis)
                f.setPixelSize(max(10, int(r * 0.26)))
                p.setFont(f)
                p.drawText(QRectF(cx - r, cy + r * 0.52, r * 2, r * 0.36),
                           int(Qt.AlignmentFlag.AlignCenter), jedn)

            r1 = mn * 0.105
            cx1 = W - r1 * 1.35 - mn * 0.03
            cy1 = H - r1 * 1.30 - mn * 0.135
            r2 = r1 * 0.66
            cx2 = cx1 - r1 - r2 * 0.92
            cy2 = cy1 + r1 * 0.30
            tarcza(cx2, cy2, r2, self._obr, 7.0, "obr/min", "x1000", czerw=5.6, duza=False)
            tarcza(cx1, cy1, r1, self._v, 140.0, "prędkość", "%d km/h" % int(self._v), czerw=125)
            # licznik przebiegu
            f = QFont("Consolas", 1); f.setPixelSize(max(10, int(r1 * 0.24))); f.setBold(True)
            p.setFont(f)
            k = QColor(140, 255, 210); k.setAlphaF(max(0.0, min(1.0, 0.85 * alfa)))
            p.setPen(k)
            p.drawText(QRectF(cx1 - r1, cy1 - r1 * 0.62, r1 * 2, r1 * 0.3),
                       int(Qt.AlignmentFlag.AlignCenter),
                       "%06.1f km" % self._licznik_km)
            f.setPixelSize(max(9, int(r1 * 0.22)))
            p.setFont(f)
            p.drawText(QRectF(cx2 - r2, cy2 - r2 * 0.66, r2 * 2, r2 * 0.32),
                       int(Qt.AlignmentFlag.AlignCenter),
                       "bieg %d" % self._bieg)

        # ═══════════ HUD ═══════════
        def _rysuj_hud(self, p, W, H, mn, t):
            if t < self.T_MAPA0:
                return
            u = _plynnie((t - self.T_MAPA0 - 0.35) / (self.T_MAPA1 - self.T_MAPA0 - 0.5))
            zan = 1.0 - _plynnie((t - self.T_RING0) / 0.5)
            if zan <= 0:
                return
            imie = str(self.dane.get("imie", "")).strip()
            f = QFont("Segoe UI", 1); f.setPixelSize(max(14, int(mn * 0.036))); f.setBold(True)
            p.setFont(f)
            k = QColor(240, 255, 248); k.setAlphaF(max(0.0, min(1.0, 0.95 * zan))); p.setPen(k)
            p.drawText(QRectF(W * 0.05, H * 0.055, W * 0.9, mn * 0.06),
                       Qt.AlignmentFlag.AlignRight,
                       ("Dzień dobry, %s" % imie) if imie else "Dzień dobry")
            f2 = QFont("Segoe UI", 1); f2.setPixelSize(max(10, int(mn * 0.020)))
            p.setFont(f2)
            k = QColor(159, 212, 184); k.setAlphaF(max(0.0, min(1.0, 0.9 * zan))); p.setPen(k)
            p.drawText(QRectF(W * 0.05, H * 0.055 + mn * 0.055, W * 0.9, mn * 0.04),
                       Qt.AlignmentFlag.AlignRight,
                       "%s · trasa dnia" % str(self.dane.get("miasto", "")).title())
            # pasek dolny
            bh = mn * 0.075
            r = QRectF(W * 0.05, H - bh - mn * 0.045, W * 0.9, bh)
            p.setPen(Qt.PenStyle.NoPen)
            k = QColor(6, 26, 18); k.setAlphaF(max(0.0, min(1.0, 0.72 * zan))); p.setBrush(k)
            p.drawRoundedRect(r, bh * 0.34, bh * 0.34)
            f3 = QFont("Segoe UI", 1); f3.setPixelSize(max(11, int(mn * 0.023))); f3.setBold(True)
            p.setFont(f3)
            k = QColor(235, 250, 242); k.setAlphaF(max(0.0, min(1.0, 0.95 * zan))); p.setPen(k)
            n_od = len(self._odhaczone); n_w = len(self.wezly)
            km_dzis = self.dane.get("km_dzis") or (self.wezly[-1]["km"] if self.wezly else 0)
            _dni = int(self.dane.get("dni", 0) or 0)
            _pasek = "%d sklepów   ·   %d km" % (n_w, int(km_dzis * min(1.0, u * 1.15)))
            if _dni > 0:
                _pasek += "   ·   %d. dzień w trasie" % _dni
            p.drawText(r.adjusted(bh * 0.5, 0, 0, 0),
                       Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, _pasek)
            k = QColor(63, 224, 163); k.setAlphaF(max(0.0, min(1.0, zan))); p.setPen(k)
            p.drawText(r.adjusted(0, 0, -bh * 0.5, 0),
                       Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                       "%d / %d odhaczone" % (n_od, n_w))

        # ═══════════ AKT 3: LOGO, PIERŚCIEŃ, ROZPAD ═══════════
        def _rysuj_final(self, p, W, H, mn, t):
            cx, cy = W * 0.5, H * 0.44
            R = mn * 0.135
            if t >= self.T_LOT0:
                zk = _plynnie((t - self.T_LOT0) / 0.9)
                p.fillRect(QRectF(0, 0, W, H), QColor(2, 14, 10, int(150 * zk)))
                k = _plynnie((t - self.T_LOT0) / (self.T_LOT1 - self.T_LOT0))
                sx, sy = self._pkt(1.0, W, H)
                lx = sx + (cx - sx) * k
                ly = sy + (cy - sy) * k - math.sin(k * math.pi) * mn * 0.22
                lr = mn * 0.02 + (R - mn * 0.02) * k
                self._rysuj_logo(p, lx, ly, lr, 1.0)
            if t >= self.T_RING0:
                kr = _plynnie((t - self.T_RING0) / (self.T_RING1 - self.T_RING0))
                rr = R * 1.62
                pen = QPen(QColor(18, 48, 36), mn * 0.016)
                p.setPen(pen); p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(QPointF(cx, cy), rr, rr)
                pen = QPen(QColor(16, 184, 129), mn * 0.016)
                pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                p.setPen(pen)
                p.drawArc(QRectF(cx - rr, cy - rr, rr * 2, rr * 2), 90 * 16, -int(360 * 16 * kr))
                f = QFont("Segoe UI", 1); f.setPixelSize(max(12, int(mn * 0.028))); f.setBold(True)
                p.setFont(f); p.setPen(QColor(201, 238, 219))
                p.drawText(QRectF(cx - rr, cy + rr + mn * 0.02, rr * 2, mn * 0.06),
                           Qt.AlignmentFlag.AlignCenter, "%d %%" % int(kr * 100))
                if kr >= 1.0:
                    f.setPixelSize(max(11, int(mn * 0.022))); p.setFont(f)
                    p.setPen(QColor(159, 212, 184))
                    _wiz = int(self.dane.get("wizyty", 0) or 0)
                    _kmr = int(self.dane.get("km_rok", 0) or 0)
                    _dni = int(self.dane.get("dni", 0) or 0)
                    if _wiz > 0 or _kmr > 0 or _dni > 0:
                        _pods = "%s wizyt · %s km · %d. dzień w trasie" % (
                            "{:,}".format(_wiz).replace(",", " "),
                            "{:,}".format(_kmr).replace(",", " "), _dni)
                    else:
                        _pods = "Dobrej trasy!"
                    p.drawText(QRectF(cx - rr * 2, cy + rr + mn * 0.085, rr * 4, mn * 0.06),
                               Qt.AlignmentFlag.AlignCenter, _pods)

        def _rysuj_logo(self, p, x, y, r, a=1.0):
            if self._logo is not None and not self._logo.isNull():
                p.setOpacity(a)
                p.drawPixmap(QRectF(x - r, y - r, r * 2, r * 2), self._logo,
                             QRectF(self._logo.rect()))
                p.setOpacity(1.0)
                return
            p.setPen(Qt.PenStyle.NoPen)
            k = QColor(16, 184, 129); k.setAlphaF(max(0.0, min(1.0, a))); p.setBrush(k)
            p.drawEllipse(QPointF(x, y), r, r)
            f = QFont("Segoe UI", 1); f.setPixelSize(int(r * 0.8)); f.setBold(True)
            p.setFont(f); p.setPen(QColor(255, 255, 255))
            p.drawText(QRectF(x - r, y - r, r * 2, r * 2),
                       Qt.AlignmentFlag.AlignCenter, "PMT")

        # ═══════════ klatka ═══════════
        def paintEvent(self, _):
            p = QPainter(self)
            try:
                p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
                W, H = float(self.width()), float(self.height())
                mn = min(W, H)
                t = self._t

                # rozpad: odłamki poprzedniej klatki
                if t >= self.T_ROZPAD0 and self._kafle is not None:
                    fr = _plynnie((t - self.T_ROZPAD0) / (self.T_ROZPAD1 - self.T_ROZPAD0))
                    p.fillRect(self.rect(), QColor(2, 16, 10, int(255 * min(1.0, fr * 1.4))))
                    for kx, ky, kw, kh, vx, vy, rot in self._kafle:
                        p.save()
                        p.translate(kx + kw / 2 + vx * fr * fr, ky + kh / 2 + vy * fr * fr)
                        p.rotate(rot * fr * 60)
                        p.setOpacity(max(0.0, 1.0 - fr * 1.25))
                        p.drawPixmap(QRectF(-kw / 2, -kh / 2, kw, kh), self._klatka_px,
                                     QRectF(kx, ky, kw, kh))
                        p.restore()
                    p.setOpacity(1.0)
                    return

                # tło
                g = QLinearGradient(0, 0, 0, H)
                if self.ciemny:
                    g.setColorAt(0.0, QColor(4, 18, 30)); g.setColorAt(0.55, QColor(7, 42, 44))
                    g.setColorAt(1.0, QColor(3, 21, 15))
                else:
                    g.setColorAt(0.0, QColor(233, 245, 240)); g.setColorAt(1.0, QColor(206, 232, 222))
                p.fillRect(self.rect(), g)

                def bezpiecznie(fn, *a):
                    try:
                        fn(*a)
                    except Exception:
                        import traceback
                        self._blad = traceback.format_exc()
                        if not getattr(self, "_blad_zapisany", False):
                            self._blad_zapisany = True
                            try:
                                with open(os.path.join(os.path.expanduser("~"),
                                                       "PMT_intro_blad.txt"), "w",
                                          encoding="utf-8") as fh:
                                    fh.write(self._blad)
                            except Exception:
                                pass

                if t < self.T_PROLOG + 0.35:
                    bezpiecznie(self._rysuj_prolog, p, W, H, mn, t)
                if self.T_PROLOG <= t < self.T_GLOB1:
                    bezpiecznie(self._rysuj_globus, p, W, H, mn, t)
                if self.T_GLOB1 <= t < self.T_MAPA0 + 0.05:
                    bezpiecznie(self._rysuj_globus, p, W, H, mn, self.T_GLOB1 - 0.001)
                    bezpiecznie(self._rysuj_tunel, p, W, H, mn, t)
                if t >= self.T_MAPA0:
                    bezpiecznie(self._rysuj_mape, p, W, H, mn, t)
                    bezpiecznie(self._rysuj_hud, p, W, H, mn, t)
                    bezpiecznie(self._rysuj_final, p, W, H, mn, t)
                if getattr(self, "_blad", None):
                    f = QFont("Segoe UI", 1); f.setPixelSize(13); p.setFont(f)
                    p.setPen(QColor(255, 170, 170))
                    p.drawText(QRectF(12, 12, W - 24, H * 0.4),
                               int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop),
                               "INTRO — błąd: " + self._blad.strip().split(chr(10))[-1][:160])

                # zasłona wejściowa
                if t < 0.35:
                    z = QColor(2, 10, 6); z.setAlphaF(max(0.0, min(1.0, 1.0 - _plynnie(t / 0.35))))
                    p.fillRect(self.rect(), z)
            except Exception:
                try:
                    import traceback
                    self._blad = traceback.format_exc()
                    if not getattr(self, "_blad_zapisany", False):
                        self._blad_zapisany = True
                        with open(os.path.join(os.path.expanduser("~"),
                                               "PMT_intro_blad.txt"), "w",
                                  encoding="utf-8") as fh:
                            fh.write(self._blad)
                    f = QFont("Segoe UI", 1); f.setPixelSize(14); p.setFont(f)
                    p.setPen(QColor(255, 170, 170))
                    p.drawText(QRectF(12, 12, self.width() - 24, self.height() - 24),
                               int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop),
                               "INTRO — błąd rysowania:\n" + self._blad[-900:])
                except Exception:
                    pass
            finally:
                p.end()

        def _przygotuj_kafle(self, W, H):
            try:
                self._klatka_px = self.grab()
                NX, NY = 7, 11
                rnd = random.Random(11)
                kw, kh = W / NX, H / NY
                self._kafle = []
                for iy in range(NY):
                    for ix in range(NX):
                        self._kafle.append((ix * kw, iy * kh, kw + 1, kh + 1,
                                            (ix / (NX - 1) - 0.5) * W * 1.6,
                                            (iy / (NY - 1) - 0.35) * H * 1.4 + H * 0.35,
                                            rnd.uniform(-1.6, 1.6)))
            except Exception:
                self._kafle = []


def pokaz_przed_startem(app, dane=None, dane_pozniej=None, katalog_zasobow="",
                        ciemny=True):
    """Intro NAJPIERW, program potem.

    Tworzy własne okno bez ramki na środku ekranu, odtwarza całą sekwencję
    we własnej pętli zdarzeń i wraca dopiero po jej zakończeniu (lub po
    kliknięciu). Dzięki temu animacja nigdy nie konkuruje z ładowaniem
    programu — nic jej nie zacina, bo w tym czasie nic innego się nie dzieje.

    Użycie w main() PRZED zbudowaniem głównego okna:

        app = QApplication(sys.argv)
        from intro_zywa_mapa import pokaz_przed_startem
        pokaz_przed_startem(app, dane={"imie": imie})
        okno = GlownaAplikacja(); okno.show()
    """
    if Qt is None:
        return False
    try:
        from PyQt6.QtCore import QEventLoop
        from PyQt6.QtWidgets import QWidget as _QW
        for _stop in (os.path.join(katalog_zasobow or "", "BEZ_INTRA.txt"),
                      os.path.join(os.path.expanduser("~"), "BEZ_INTRA.txt")):
            if os.path.exists(_stop):
                return False
        ekr = app.primaryScreen().geometry()          # CAŁY ekran
        okno = _QW(None, Qt.WindowType.FramelessWindowHint
                   | Qt.WindowType.WindowStaysOnTopHint)
        okno.setStyleSheet("background:#04121e;")
        okno.setGeometry(ekr)
        w = IntroZywaMapa(okno, dane, katalog_zasobow, ciemny)
        w.setGeometry(0, 0, ekr.width(), ekr.height())
        petla = QEventLoop()
        w.zakonczony.connect(petla.quit)
        okno.showFullScreen()
        w.show()
        w.raise_()
        okno.raise_()
        okno.activateWindow()
        if dane_pozniej:
            import threading

            def _w_tle():
                try:
                    d = dane_pozniej() or {}
                except Exception:
                    d = {}
                try:
                    w.daneGotowe.emit(d)
                except Exception:
                    pass
            threading.Thread(target=_w_tle, daemon=True).start()
        petla.exec()
        okno.close()
        okno.deleteLater()
        return True
    except Exception:
        try:
            import traceback
            with open(os.path.join(os.path.expanduser("~"),
                                   "PMT_intro_blad.txt"), "w", encoding="utf-8") as fh:
                fh.write(traceback.format_exc())
        except Exception:
            pass
        return False


def sprobuj_intro(rodzic, dane=None, po_zakonczeniu=None, katalog_zasobow="",
                  ciemny=True, dane_pozniej=None):
    """Uruchamia intro jako nakładkę w oknie programu. True = wystartowało.

    dane_pozniej — funkcja BEZ dostępu do interfejsu, wykonywana w tle
    (np. odczyt planu wizyt). Jej wynik dołącza do intra, gdy będzie
    gotowy; start programu nigdy na nią nie czeka.
    """
    if Qt is None:
        return False
    try:
        kat = katalog_zasobow or ""
        for _stop in (os.path.join(kat, "BEZ_INTRA.txt"),
                      os.path.join(os.path.expanduser("~"), "BEZ_INTRA.txt")):
            if os.path.exists(_stop):
                return False
        w = IntroZywaMapa(rodzic, dane, katalog_zasobow, ciemny)
        if dane_pozniej:
            import threading

            def _w_tle():
                try:
                    d = dane_pozniej() or {}
                except Exception:
                    d = {}
                try:
                    w.daneGotowe.emit(d)
                except Exception:
                    pass
            threading.Thread(target=_w_tle, daemon=True).start()
        if po_zakonczeniu:
            w.zakonczony.connect(po_zakonczeniu)
        w.setGeometry(rodzic.rect())
        w.raise_()
        w.show()
        try:
            # bez fokusu klawisz (Esc, spacja…) nie pomijał intra — działał
            # tylko klik myszą
            w.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
            w.setFocus()
        except Exception:
            pass
        return True
    except Exception:
        try:
            import traceback
            with open(os.path.join(os.path.expanduser("~"),
                                   "PMT_intro_blad.txt"), "w", encoding="utf-8") as f:
                f.write(traceback.format_exc())
        except Exception:
            pass
        return False
